export const blocks: readonly LiturgyBlock[] = [
  {"id": "ru-mol-0001", "section": "service", "who": "rubric", "text": "Алексию, митр. Московскому и всея России, чудотворцу,"},
  {"id": "ru-mol-0002", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0003", "section": "service", "who": "reader", "text": "Перевод: К разделяющему престол с апостолами, и целителю прекрасному, и служителю угодному Богу, к раке твоей почитаемой приходим, святитель Алексий Богомудрый, чудотворец, собравшись с любовью в день памяти твоей светло празднуем, радуясь в псалмопениях и песнопениях духовных и прославляя Христа, даровавшего тебе такую благодать исцелений и городу твоему великую силу."},
  {"id": "ru-mol-0004", "section": "service", "who": "rubric", "text": "Ин тропарь, на обретение мощей,"},
  {"id": "ru-mol-0005", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0006", "section": "service", "who": "reader", "text": "Перевод: Как драгоценное сокровище, на многие годы сокрытое под землей, мы обрели чудотворящие почитаемые мощи твои, всеблаженный отче святитель Алексий, от них же принимая исцеления, обогащаемся и прославляем Христа, говоря: «Слава Прославляющему святых Своих»."},
  {"id": "ru-mol-0007", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0008", "section": "service", "who": "rubric", "text": "Амфилохию, еп. Владимира Волынского,"},
  {"id": "ru-mol-0009", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0010", "section": "service", "who": "reader", "text": "Перевод: От мирской суеты удалившись, в пещерах Киевских Феодосия блаженного Богомудро поселился ты, святитель Христов, отче Амфилохий, и там в епископа Богоспасаемой пастве Владимиро-Волынской поставленный, в трудах, бдениях и пощении свято подвизался ты. И так достигнув совершенства добродетелей, снова в пещеры святые возвратился, где и дух свой благочестиво предал ты Господу, почитаемый, к лику преподобных Печерских причтенный, с ними же молись Христу, почитаемый, о спасении душ наших."},
  {"id": "ru-mol-0011", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0012", "section": "service", "who": "rubric", "text": "Андрею, архиеп. Критскому,"},
  {"id": "ru-mol-0013", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0014", "section": "service", "who": "reader", "text": "Перевод: Христову Церковь ты возрадовал, лирой языка твоего искусно воспевая, богословием же славу Восхваляемой Троицы всем ясно показал, потому и мы тебя, как объясняющего тайны Божии, воспеваем, Андрей, пастырь Критский, и величаем память твою, прославляя Христа, удивительного во святых Своих (Пс.67:36)."},
  {"id": "ru-mol-0015", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0016", "section": "service", "who": "rubric", "text": "Антонию Вологодскому,"},
  {"id": "ru-mol-0017", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0018", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0019", "section": "service", "who": "rubric", "text": "Арсению, архиеп. Сербскому,"},
  {"id": "ru-mol-0020", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0021", "section": "service", "who": "reader", "text": "Перевод: Милости наставник и милосердия сокровищница, которую ты всем открыл, православия учитель и архиереев священное украшение, отче наш иерарх Арсений, ты был защитником нищих, потому моли Христа Бога просветить души наши, да не уснем мы смертным сном."},
  {"id": "ru-mol-0022", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0023", "section": "service", "who": "rubric", "text": "Арсению, еп. Тверскому,"},
  {"id": "ru-mol-0024", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0025", "section": "service", "who": "reader", "text": "Перевод: Благочестиво пребывая в чине святителя, просветил людей своим учением и для храма Пречистой [Богородицы] много потрудился, и заботился о монашеской братии, из-за этого от Христа принял венец твоей паствы. Поэтому, как наместника апостольского престола и великого святителя почитая тебя, молим тебя, блаженный, чада твои: от всех бед избавь нас ко Христу твоими молитвами, святитель Христов Арсений, отец наш."},
  {"id": "ru-mol-0026", "section": "service", "who": "rubric", "text": "Ин тропарь, на перенесение мощей,"},
  {"id": "ru-mol-0027", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0028", "section": "service", "who": "reader", "text": "Перевод: Божественной свыше просветился благодатью, святитель, и со многим терпением во временной жизни совершил ты подвиг. Потому источаешь благодать чудес всем с верой приходящим к почитаемой раке с мощами твоими, Арсений преблаженный. Мы же взываем к тебе: «Слава Давшему тебе силу, слава Венчавшему тебя, слава Подающему через тебя всем исцеления»."},
  {"id": "ru-mol-0029", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0030", "section": "service", "who": "rubric", "text": "Афанасию Великому, архиеп. Александрийскому,"},
  {"id": "ru-mol-0031", "section": "service", "who": "rubric", "text": "глас 3:"},
  {"id": "ru-mol-0032", "section": "service", "who": "reader", "text": "Перевод: Ты сделался столпом православия, божественными догматами утверждая Церковь, иерарх Афанасий, ибо Сына единосущным Отцу провозгласив, ты посрамил Ария. Отче преподобный, Христа Бога моли, даровать нам великую милость."},
  {"id": "ru-mol-0033", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0034", "section": "service", "who": "rubric", "text": "Афанасию, патриарху Цареградскому,"},
  {"id": "ru-mol-0035", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0036", "section": "service", "who": "reader", "text": "Перевод: Светом чистоты жизни ты сжег терния страстей и потоками слез напоил бесплодную землю, сделав душевную ниву многоплодной, Афанасий преблаженный, светило Константинополя, патриархов украшение, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0037", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0038", "section": "service", "who": "rubric", "text": "Афанасию, патриарху Цареградскому, Лубенскому чудотворцу,"},
  {"id": "ru-mol-0039", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0040", "section": "service", "who": "reader", "text": "Перевод: Премудростью учений твоих просветив царствующий город (Константинополь), ты разогнал мрак еретического невежества, преблаженный, твое благословение земле российской принес, отче наш, святитель Афанасий, где окончив путь свой, на крыльях чистоты взлетел ты в Небесное Царство. Моли Христа Бога непрестанно о душах наших."},
  {"id": "ru-mol-0041", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0042", "section": "service", "who": "rubric", "text": "Варсонофию, еп. Тверскому,"},
  {"id": "ru-mol-0043", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0044", "section": "service", "who": "reader", "text": "Перевод: Вестник спасительного пути, истинный хранитель апостольских преданий, непоколебимый столп, учитель благочестия и наставник Православия, святитель Варсонофий, моли Владыку всех даровать вселенной мир и душам нашим великую милость."},
  {"id": "ru-mol-0045", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0046", "section": "service", "who": "rubric", "text": "Василию Великому, архиеп. Кесарии Каппадокийской,"},
  {"id": "ru-mol-0047", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0048", "section": "service", "who": "reader", "text": "Перевод: По всей земле прошел голос твой, ибо приняла она слово твое: им ты истины веры богодостойно изложил, природу всего существующего изъяснил, человеческие обычаи благоукрасил, царственный священник, отче преподобный, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0049", "section": "service", "who": "rubric", "text": "Величание"},
  {"id": "ru-mol-0050", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0051", "section": "service", "who": "rubric", "text": "Василию, еп. Захолмскому (Серб.),"},
  {"id": "ru-mol-0052", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0053", "section": "service", "who": "reader", "text": "Перевод: С юности твоей всего себя Господу отдал, пребывая в молитвах, подвигах и постах, отец Богоносный, примером добродетели был для своего стада, поэтому Бог, видя твое благое произволение, поставил тебя пастырем и прекрасным архиереем Своей Церкви, и по преставлении твоем сохранил святое тело твое нетленным, святитель Василий. Потому, как имеющий дерзновение, молись Христу Богу о спасении душ наших."},
  {"id": "ru-mol-0054", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0055", "section": "service", "who": "rubric", "text": "Василию, еп. Рязанскому,"},
  {"id": "ru-mol-0056", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0057", "section": "service", "who": "reader", "text": "Перевод: Сначала ты был почтен святительским саном в Муроме, но из него неправедно изгоняем, ты взошел на свою (епископскую) мантию, как на легкий корабль, и на ней, сверхъестественно, как бесплотный, совершая путь по воде, направляемый Промыслом Всевышнего и заступничеством Богоматери, ты достиг Богоспасаемого города Рязани, и в нем принял архиерейский престол, Богом данную тебе паству рязанскую ты отлично упас, святитель наш отче Василий, моли Христа Бога о спасении наших душ."},
  {"id": "ru-mol-0058", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0059", "section": "service", "who": "rubric", "text": "Геннадию, архиеп. Новгородскому,"},
  {"id": "ru-mol-0060", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-0061", "section": "service", "who": "reader", "text": "Перевод: Уподобился ты древним отцам, святитель отче Геннадий, священные книги собрав и еретиков посрамив, ревность о Боге являя, паству защитил ты, моли и сейчас Христа Бога мир Церкви даровать и спастись душам нашим."},
  {"id": "ru-mol-0062", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0063", "section": "service", "who": "rubric", "text": "Герасиму, еп. Великопермскому, Устьвымскому,"},
  {"id": "ru-mol-0064", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0065", "section": "service", "who": "reader", "text": "Перевод: Проповедью веры в Бога землю Зырянскую озарил ты и ко Христу многих людей привел. Взывает же ко Господу вместе с твоей и кровь Авеля и Захарии (Мф.23:35), отче Герасим, моли Христа Бога пастве твоей и всем с любовью совершающим память твою, даровать великую милость."},
  {"id": "ru-mol-0066", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0067", "section": "service", "who": "rubric", "text": "Герасиму, Питириму и Ионе, епп. Великопермским, Устьвымским,"},
  {"id": "ru-mol-0068", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0069", "section": "service", "who": "reader", "text": "Перевод: Равноапостольного святителя Стефана преемники, светом Православия землю Зырянскую озарившие, святители Христовы Герасим, Питирим и Иона, престолу Пресвятой Троицы сейчас предстоя, молитесь о том, чтобы на паству вашу не напали враги и о мирном спасении всех православных людей."},
  {"id": "ru-mol-0070", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0071", "section": "service", "who": "rubric", "text": "Герману, архиеп. Казанскому,"},
  {"id": "ru-mol-0072", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0073", "section": "service", "who": "reader", "text": "Перевод: С юности иго Христово ревностно подняв, бденными подвигами поста и молитвы ты прославился. Потому ты был призван Богом на служение Церкви в новопросвещенном царстве Казанском, вместе со святителем Гурием, где ты стал главою созданной тобой в городе Свияжске обители, и достойным преемником первосвятителю. Духом предстоя Престолу Владыки, молись святитель Герман, со святителем Гурием, православной пастве в благочестии преуспевать, и тьме иноверия светом веры разгоняться."},
  {"id": "ru-mol-0074", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0075", "section": "service", "who": "rubric", "text": "Геронтию, митр. Московскому и всея Руси,"},
  {"id": "ru-mol-0076", "section": "service", "who": "rubric", "text": "глас 6"},
  {"id": "ru-mol-0077", "section": "service", "who": "reader", "text": "Перевод: Сегодня всякая душа радуется в день памяти успения святителя Христова Геронтия, ревнителя премудрости и учителя кротости, наставника смирения, насладившего верующих учением слова Божия. Русского митрополита прославим, принявшего паству как святитель, украсившего Церковь Христову. Потому и Христос, видя твое доброе намерение, причел тебя к собранию праведных, святитель Геронтий, моли Христа Бога и Пречистую Богородицу не переставая обо всех нас."},
  {"id": "ru-mol-0078", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0079", "section": "service", "who": "rubric", "text": "Григорию Богослову, архиеп. Константинопольскому,"},
  {"id": "ru-mol-0080", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0081", "section": "service", "who": "reader", "text": "Перевод: Пастырская свирель богословия твоего победила трубы риторов, ибо, как взыскавшему глубин Духа, и красота слова была дарована тебе. Но ходатайствуй пред Христом Богом, отче Григорий, о спасении душ наших."},
  {"id": "ru-mol-0082", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0083", "section": "service", "who": "rubric", "text": "Григорию Двоеслову, папе Римскому,"},
  {"id": "ru-mol-0084", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0085", "section": "service", "who": "reader", "text": "Перевод: Восприняв от Бога свыше Божественную благодать, славный Григорий, и Его силой укрепляем, ты жил в соответствии с Евангелием. Поэтому у Христа получил награду за труды, всеблаженный, Его же моли о спасении душ наших."},
  {"id": "ru-mol-0086", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0087", "section": "service", "who": "rubric", "text": "Григорию Паламе, архиеп. Фессалонитскому,"},
  {"id": "ru-mol-0088", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0089", "section": "service", "who": "reader", "text": "Перевод: Православия учитель, святителей украшение, богословов защитник непобедимый, Григорий чудотворец, Салоник великая хвала, провозвестник благодати, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0090", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0091", "section": "service", "who": "rubric", "text": "Григорию Чудотворцу, еп. Неокесарийскому,"},
  {"id": "ru-mol-0092", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0093", "section": "service", "who": "reader", "text": "Перевод: В молитвах бодрствуя (от греч. γρηγορέω — бодрствую) и чудеса творя, ты стал именоваться по делам своим. Но молись Христу Богу, отче Григорий, просветить души наши, да не умрем во грехах наших."},
  {"id": "ru-mol-0094", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0095", "section": "service", "who": "rubric", "text": "Гурию, архиеп. Казанскому,"},
  {"id": "ru-mol-0096", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0097", "section": "service", "who": "reader", "text": "Перевод: Правило веры и образ целомудрия, учителя добрых дел и наставника спасения, даровал тебя Господь новопросвещенному городу Казани, в нем же обрел ты новых людей из язычников и привел их ко Христу. Потому в день памяти твоей радостно собравшись, с почтением празднуем святое твое успение, ты же, отче наш, святитель Христов Гурий, моли Христа Бога о спасении наших душ."},
  {"id": "ru-mol-0098", "section": "service", "who": "rubric", "text": "Ин тропарь, на перенесение мощей,"},
  {"id": "ru-mol-0099", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0100", "section": "service", "who": "reader", "text": "Перевод: Как благоухающая лилия, мироточивые твои мощи из сада Церкви Спасителя в сад Церкви Богородицы с почитанием перенесены, святитель Гурий, ибо, как драгоценный дар, тебя даровал Христос Пречистой Матери Своей и наполнился храм Ее святой благоуханием твоим, и возрадовался архиерейский престол, принимающий тебя, старейшину своего. Восторжествовало и собрание верующих со святителем и священноначальниками о преславном перенесении подающих исцеления мощей твоих, которое мы с радостью празднуя, молим тебя, угодник Божий: «Моли Христа Бога подать душам нашим мир и великую милость»."},
  {"id": "ru-mol-0101", "section": "service", "who": "rubric", "text": "Ин тропарь, на обретение мощей,"},
  {"id": "ru-mol-0102", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0103", "section": "service", "who": "reader", "text": "Перевод: Первые учителя прежде темного, сейчас же светлого и новопросвещенного города Казани, первые возвестители спасительного пути, истинные хранители апостольских преданий, непоколебимые столпы, учителя благочестия и наставники Православия, Гурий и Варсонофий, молите Владыку всех даровать вселенной мир и душам нашим великую милость."},
  {"id": "ru-mol-0104", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0105", "section": "service", "who": "rubric", "text": "Даниилу, архиеп. Сербскому,"},
  {"id": "ru-mol-0106", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0107", "section": "service", "who": "reader", "text": "Перевод: Явившись чудом разумения, делами добродетелей Божиих воссиял ты, монашествующих собрание упас ты, архиерейские кафедры утвердил, еретического нападения не побоявшись, Церковью Христовой управляя, преподобный отче, Даниил премудрый, ты почил, как уснул, и тело твое целым и нетленным сохраняется и подает исцеления больным от различных болезней и прогоняет демонов. Потому молим тебя: молись о спасении душ наших."},
  {"id": "ru-mol-0108", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0109", "section": "service", "who": "rubric", "text": "Димитрию, митр. Ростовскому,"},
  {"id": "ru-mol-0110", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0111", "section": "service", "who": "reader", "text": "Перевод: Православия ревнитель и раскола искоренитель, Российский целитель и новый к Богу молитвенник, сочинениями твоими неразумных ты вразумил, лира духовная, Димитрий блаженный, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0112", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0113", "section": "service", "who": "rubric", "text": "Димитрию, митр. Ростовскому, Митрофану и Тихону, епп. Воронежским,"},
  {"id": "ru-mol-0114", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0115", "section": "service", "who": "reader", "text": "Перевод: Как раньше на Востоке три великих святителя: сильный словом Василий, глубина Богословия Григорий и Златоустый Иоанн, так и сейчас в стране северной три новых явленных нам светила веры взошли на небе церковном: столп веры Митрофан, слово истины в лицо царю исповедавший, и обличитель раскола Димитрий, обоюдоострым мечом все козни его рассекший, и полный благодати сосуд Тихон, тишиной слов своих грешников к покаянию призвавший. О великие три святителя земли Русской, молите Христа Бога, Ему же вы были угодны, о спасении душ наших."},
  {"id": "ru-mol-0116", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0117", "section": "service", "who": "rubric", "text": "Дионисию, архиеп. Суздальскому,"},
  {"id": "ru-mol-0118", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0119", "section": "service", "who": "reader", "text": "Перевод: Православия ревнитель, благочестия наставник, ищущим спасения хороший руководитель, монашествующих Богодухновенное украшение, Богоносного Евфимия собеседник, святитель Дионисий, учением и добродетелями Отечество твое просветил ты, не забывай нас, почитающих тебя, но жизнью нашей мирно управляй."},
  {"id": "ru-mol-0120", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0121", "section": "service", "who": "rubric", "text": "Донату, еп. Еврии,"},
  {"id": "ru-mol-0122", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0123", "section": "service", "who": "reader", "text": "Перевод: Блаженным деятелем и благоустроителем Церкви Христовой ты был, отче Донат, не переставая заботился о своем стаде, научая и руководя его в любви Сына Божия, ибо не только в твоем городе много народа, но и в Константинополе императора и всех людей в нем ты удивил достойными славы чудесами твоими. Угодные Богу молитвы совершая ко Христу Богу, ты явился быстрым помощником всем. Предстоя Всесвятой Троице на Небесах, моли Ее обо всех нас, да спасет души наши."},
  {"id": "ru-mol-0124", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0125", "section": "service", "who": "rubric", "text": "Евстафию I, архиеп. Сербскому,"},
  {"id": "ru-mol-0126", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0127", "section": "service", "who": "reader", "text": "Перевод: Избранный Богом и возлюбленный людьми, архиереев священное украшение, отче Евстафий, сослужитель Ангелов, ты был проповедником тайн Божественных, потому моли Христа Бога со всеми святыми об избавлении от всякого зла по молитвам твоим, блаженный, и о спасении нас, почитающих с любовью святую память твою."},
  {"id": "ru-mol-0128", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0129", "section": "service", "who": "rubric", "text": "Евфимию, патриарху Болгарскому,"},
  {"id": "ru-mol-0130", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0131", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0132", "section": "service", "who": "rubric", "text": "Евфимию, архиеп. Новгородскому, чудотворцу,"},
  {"id": "ru-mol-0133", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0134", "section": "service", "who": "reader", "text": "Перевод: Ты был избран Богом с юности, святитель Евфимий, и потому был почтен архиерейским саном, ты руководил духовной жизнью людей, врученных тебе Богом, поэтому и после смерти своей ты получил от Господа дар чудесным образом исцелять различные болезни. Моли Бога о нас, празднующих твою дорогую память и всегда прославляющих тебя."},
  {"id": "ru-mol-0135", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0136", "section": "service", "who": "rubric", "text": "Ефрему, патриарху Сербскому,"},
  {"id": "ru-mol-0137", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0138", "section": "service", "who": "reader", "text": "Перевод: Патриархов великое украшение, святителей красоту, монахов пример, пустынников славу, милости подателя, духовных толкований светильника, собравшись, верующие, прославим, кротости учителя, заботящегося о Божественном, премудрого архиерея, великого святителя и отца, Ефрема, Патриарха Сербского, звезду, темных людей просвещающую и всех верующих озаряющую. Потому, приходя к раке с мощами его, с любовью прикладываемся к ним и взываем: «Святитель святой, не переставай молить Христа Бога о спасении наших душ»."},
  {"id": "ru-mol-0139", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0140", "section": "service", "who": "rubric", "text": "Иакову, еп. Ростовскому,"},
  {"id": "ru-mol-0141", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0142", "section": "service", "who": "reader", "text": "Перевод: Избран с юности Богом был, святитель Иаков, потому был почтен архиерейским саном, упас ты людей, врученных тебе Богом, потому и после успения получил от Бога чудесный дар исцеления различных болезней. Моли о нас, празднующих почтенную память твою, да тебя непрестанно прославляем."},
  {"id": "ru-mol-0143", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0144", "section": "service", "who": "rubric", "text": "Игнатию Брянчанинову, еп. Кавказскому и Черноморскому,"},
  {"id": "ru-mol-0145", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0146", "section": "service", "who": "reader", "text": "Перевод: Ревностный защитник православия, покаяния и молитвы деятель и учитель особенный, архиереев богодухновенное украшение, монашествующих слава и честь: твоими писаниями ты всех нас привел к целомудрию. Лира духовная, Игнатий богомудрый, моли Слово Христа Бога, Его же ты носил в сердце своем, даровать нам покаяние, прежде нашей смерти."},
  {"id": "ru-mol-0147", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0148", "section": "service", "who": "rubric", "text": "Игнатию, еп. Ростовскому,"},
  {"id": "ru-mol-0149", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0150", "section": "service", "who": "reader", "text": "Перевод: Просветившись учением благой веры, ты принял паству как святитель и был наследником апостолов, потому и принял ты от Бога дар чудес, святитель отче Игнатий, моли Христа Бога о спасении наших душ."},
  {"id": "ru-mol-0151", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0152", "section": "service", "who": "rubric", "text": "Илариону, еп. Меглинскому,"},
  {"id": "ru-mol-0153", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0154", "section": "service", "who": "reader", "text": "Перевод: Став чудесным основанием, воссиял ты делами добродетелей Божиих, собрание монашествующих упас, архиерейские кафедры очистил, еретического же нападения не побоявшись, храм Христов ты воздвиг, преподобный Иларион, умер, как заснул, и тело твое, сохранившись нетленным и целым, подает исцеления больным от различных болезней и прогоняет демонов, потому молим тебя: моли о спасении душ наших."},
  {"id": "ru-mol-0155", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0156", "section": "service", "who": "rubric", "text": "Илариону, митр. Суздальскому,"},
  {"id": "ru-mol-0157", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-0158", "section": "service", "who": "reader", "text": "Перевод: Воспойте, все люди, в Трех Ипостасях Единого Бога, на Небесах непостижимо пребывающего, устроением всем управляющего, на землю милосердно взирающего, в пустыни твердо стоящего против невидимых врагов угодника Своего преподобного Илариона укрепляющего, по молитвам которого, Боже, помилуй и спаси нас."},
  {"id": "ru-mol-0159", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0160", "section": "service", "who": "rubric", "text": "Иннокентию, еп. Иркутскому,"},
  {"id": "ru-mol-0161", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0162", "section": "service", "who": "reader", "text": "Перевод: Светильник Церкви преяркий, озаривший лучами добродетелей своих страну эту, и многими исцелениями приходящих к тебе с верой Бога прославивший, молим тебя, святитель отче Иннокентий, охраняй молитвами твоими город этот от всех бед и скорбей."},
  {"id": "ru-mol-0163", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0164", "section": "service", "who": "rubric", "text": "Иннокентию, митр. Московскому,"},
  {"id": "ru-mol-0165", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0166", "section": "service", "who": "reader", "text": "Перевод: По всему Северу прошла проповедь твоя, поскольку принявших слово твоё, которым ты богодостойно раскрыл истины веры, незнающих Христа ты просветил светом Евангелия, облагородил человеческие нравы, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0167", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0168", "section": "service", "who": "rubric", "text": "Иннокентию, архиеп. Херсонскому,"},
  {"id": "ru-mol-0169", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0170", "section": "service", "who": "reader", "text": "Перевод: С юных лет усердно внимая учению благочестия и страха Божия, преуспевая в благодати Божией, ты обрел дар слова и явился неутомимым проповедником спасения, озаряя души верующих спасительным пониманием и приводя всех к исправлению. Святитель отче Иннокентий, моли Христа Бога дать нам прощение грехов и великую милость."},
  {"id": "ru-mol-0171", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0172", "section": "service", "who": "rubric", "text": "Иоанну Златоусту, архиеп. Константинопольскому,"},
  {"id": "ru-mol-0173", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0174", "section": "service", "who": "reader", "text": "Перевод: Воссиявшая как светоч огненный уст твоих благодать вселенную просветила; нестяжания сокровище для мира ты собрал, высоту смиренномудрия нам показал. Но, словами твоими нас наставляя, отче Иоанн Златоустый, моли Слово, Христа Бога, о спасении душ наших."},
  {"id": "ru-mol-0175", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0176", "section": "service", "who": "rubric", "text": "Иоанну Милостивому, патриарху Александрийскому,"},
  {"id": "ru-mol-0177", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0178", "section": "service", "who": "reader", "text": "Перевод: В терпении твоем стяжал ты награду свою, отче преподобный, в молитвах непрестанно пребывавший, нищих возлюбивший и им помогавший, но молись Христу Богу, Иоанн милостивый, блаженный, о спасении душ наших."},
  {"id": "ru-mol-0179", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0180", "section": "service", "who": "rubric", "text": "Иоанну, архиеп. Новгородскому,"},
  {"id": "ru-mol-0181", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0182", "section": "service", "who": "reader", "text": "Перевод: Сегодня светло радуется славнейший Великий Новгород, имея мощи твои у себя, святитель Иоанн, как солнечные лучи испускающие и подающие исцеления приходящим к раке с мощами твоими. Молись Христу Богу о сохранении города этого невредимым от языческого пленения, и междоусобной войны, и сожжения в пожаре, святитель богомудрый и творящий чудеса, Небесный человек и земной ангел, да собравшись с любовью в день памяти твоей, светло празднуем, в псалмопении и песнопениях духовных радуясь и Христа прославляя, даровавшего тебе такую благодать исцелений и Великому Новгороду защиту и силу."},
  {"id": "ru-mol-0183", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0184", "section": "service", "who": "rubric", "text": "Иоанну, еп. Суздальскому,"},
  {"id": "ru-mol-0185", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0186", "section": "service", "who": "reader", "text": "Перевод: Направляя Церковь Божию Соборную и Апостольскую, соблюдая заповеди Божии, весьма прекрасно упас стадо разумных овец, враждебным церковникам молитвою твоей повелел прозреть, сначала связав, а потом разрешив им грехи (Мф.18:18), тем самым вразумив их, как ранее святой Леонтий, помощник спасения Русской земли, учитель Ростовский, так и ты — святой епископ Суздальский, избавитель от напастей всех приходящих к тебе, чудотворец Иоанн, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0187", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0188", "section": "service", "who": "rubric", "text": "Иоанну, митр. Тобольскому,"},
  {"id": "ru-mol-0189", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0190", "section": "service", "who": "reader", "text": "Перевод: Учитель благочестия, сирот воспитатель, утешитель скорбящих, больным бескорыстный врач, страдающим душой быстрый помощник, усердный молитвенник обо всех ко Господу, святитель отче Иоанн, моли Христа Бога о спасении наших душ."},
  {"id": "ru-mol-0191", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0192", "section": "service", "who": "rubric", "text": "Иоанну и Феодору, епп. Суздальским,"},
  {"id": "ru-mol-0193", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0194", "section": "service", "who": "reader", "text": "Перевод: Как единомысленных с апостолами учителей Суздальского края, и премудрых целителей душ и тел, и служителей Богу угодных, прославляем вас, приходя к ракам с почитаемыми мощами вашими, святители Богоблаженные, Феодор и Иоанн, в псалмопениях и песнопениях духовных, радуясь, славим Христа, даровавшего вам благодать исцелений и городу нашему Суздалю великую в вас силу."},
  {"id": "ru-mol-0195", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0196", "section": "service", "who": "rubric", "text": "Иоанну (Максимовичу), архиеп. Шанхайскому и Сан-Францисскому,"},
  {"id": "ru-mol-0197", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-0198", "section": "service", "who": "reader", "text": "Перевод: Попечение твое о пастве в странствии ее, вот предзнаменование и молитв твоих, за весь мир всегда возносимых. Так веруем, познав любовь твою, святитель и чудотворец Иоанн! Весь Богом освященный священнодействием пречистых Тайн, ими же и сам всегда укрепляемый, ты торопился к страдающим, целитель, облегчающий скорби. Поспеши и сейчас на помощь к нам, всем сердцем почитающим тебя."},
  {"id": "ru-mol-0199", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0200", "section": "service", "who": "rubric", "text": "Иоасафу, еп. Белгородскому,"},
  {"id": "ru-mol-0201", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0202", "section": "service", "who": "reader", "text": "Перевод: Святитель, Христом Богом возлюбленный, ты был образцом веры и примером милосердия для людей, бдением же, постом и молитвой, как преяркий светильник просиял ты, и был прославлен Богом, ибо телом ты почиваешь в нетлении, духом же Престолу Божию предстоишь и чудеса удивительно источаешь. Моли Христа Бога, да утвердит нас в Православии и благочестии и спасет души наши."},
  {"id": "ru-mol-0203", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0204", "section": "service", "who": "rubric", "text": "Иову, патриарху Московскому и всея Руси,"},
  {"id": "ru-mol-0205", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0206", "section": "service", "who": "reader", "text": "Перевод: Да торжествует Церковь Христова и да радуется город Москва, так как воссиял светильник земли Российской, в исповедании Истины непоколебимый Патриарх Иов, по его же молитвам, Господи, все искушения мира этого и ереси искорени, людей направь к благочестию и укрепи их в Православии."},
  {"id": "ru-mol-0207", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0208", "section": "service", "who": "rubric", "text": "Ионе, еп. Великопермскому,"},
  {"id": "ru-mol-0209", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0210", "section": "service", "who": "reader", "text": "Перевод: Просветитель Вятской земли, строитель храмов Божиих, ревнитель церковного благообразия, подражатель преподобному Трифону, святитель отче Иона, не оставь чад твоих, в скорбях находящихся, но огради нас молитвами твоими ко Господу, да спасет души наши."},
  {"id": "ru-mol-0211", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0212", "section": "service", "who": "rubric", "text": "Ионе, митр. Московскому и всея России, чудотворцу,"},
  {"id": "ru-mol-0213", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0214", "section": "service", "who": "reader", "text": "Перевод: С детства приняв иго Господне (Мф.11:30) и устремившись бесповоротно по Его пути, ты достиг труда священнослужения, получил паству как епископ и принял дар чудотворений от Бога. Всем с верой приходящим к раке с мощами твоими ты неистощимо подаешь излечения от различных болезней, отче наш Иона, святитель Христов, моли Христа Бога даровать нам великую милость."},
  {"id": "ru-mol-0215", "section": "service", "who": "rubric", "text": "Ин тропарь, на перенесение мощей,"},
  {"id": "ru-mol-0216", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0217", "section": "service", "who": "reader", "text": "Перевод: С юности своей посвятив всего себя Господу, в молитвах, трудах и постах ты был примером добродетели, потому Бог, увидев твое доброе намерение, сделал тебя архиереем и пастырем Своей Церкви. Поэтому и по преставлении, почитаемое тело твое целое и нетленное сохраняется, Иона святитель, моли Христа Бога, да спасет души наши."},
  {"id": "ru-mol-0218", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0219", "section": "service", "who": "rubric", "text": "Ионе, архиеп. Новгородскому,"},
  {"id": "ru-mol-0220", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0221", "section": "service", "who": "reader", "text": "Перевод: Исполнение веры и образ кротости, как сад посреди рая, преподобными делами твоими мир просвещаешь, потому к мощам твоим с любовью прикасаемся и с верой взываем: «Приди на помощь воспевающим память твою светоносную, отче Иона, и моли о спасении душ наших»."},
  {"id": "ru-mol-0222", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0223", "section": "service", "who": "rubric", "text": "Исаии, еп. Ростовскому, чудотворцу,"},
  {"id": "ru-mol-0224", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0225", "section": "service", "who": "reader", "text": "Перевод: Показавший себя весьма опытным среди монахов святой Печерской Лавры и бывший добрым пастырем (Ин.10:11) своего стада в архиерейском сане, Боголюбивый Исаия, моли о нас Пастыреначальника Христа Бога да помилует и спасет души наши."},
  {"id": "ru-mol-0226", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0227", "section": "service", "who": "rubric", "text": "Иувеналию, патриарху Иерусалимскому,"},
  {"id": "ru-mol-0228", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0229", "section": "service", "who": "reader", "text": "Перевод: Брата Господня на престоле архиерейском преемник, святого города Иерусалим иерарх достойный славы, вместе с Богомудрыми отцами в Халкидоне ты объяснил воплощение Сына Божия, пришедшего в мир обновить и обожить всех людей, в Церкви Его с Ним сочетавшись, святитель отче Иувеналий, предстоя сейчас в Царствии Отца светов (Иак.1:17), молись о почитающих тебя с любовью, да будет с нами мир и милость Спасителя."},
  {"id": "ru-mol-0230", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0231", "section": "service", "who": "rubric", "text": "Киприану, митр. Московскому, всея России чудотворцу,"},
  {"id": "ru-mol-0232", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0233", "section": "service", "who": "reader", "text": "Перевод: Будучи освящен от Бога свыше Божественной благодатью и украшен добродетельным нравом, просвещен Духом Святым, совершив святыню в страхе Божием (2Кор.7:1), ты удостоился благодати Божественного Духа, пасущий Церковь Божию Русской митрополии, постом все побеждая, испытания претерпев, гонения пройдя, святого митрополита Петра всегда себе в помощь призывая и его имея помощником, и следуя по его стопам. Служитель благоугодный, заповеди Божии соблюдая, Духом Божиим наставляем, просвещая верующих учением твоим, пощением украсил жизнь свою, ярмо Господне с молодости подняв и больше всех Христа возлюбив. Потому и архиерейской кафедрой почтен и, как сияющее солнце, произойдя из Сербской земли, во все концы Русской земли добродетелью просияв, ты явился светилом миру и преставился ко Господу от этой жизни в вечный покой, великий архиерей Божий, митрополит Киприан, учитель и наставник Русской земли, всегда предстоя Престолу Пресвятой Троицы, моли Господа усердно об архиереях и обо всех христианах, да спасет по молитвам твоим души наши."},
  {"id": "ru-mol-0234", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0235", "section": "service", "who": "rubric", "text": "Киприану, Фотию и Ионе, митр. Московским и всея Руси, на перенесение мощей,"},
  {"id": "ru-mol-0236", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0237", "section": "service", "who": "reader", "text": "Перевод: Как звезды, сияющие от Яркого Солнца, Светом Троицы озаряете сердца верующих перенесением почитаемых мощей ваших. Вы явились чистыми сосудами Троицы в своей жизни и научили людей твердо вере Христовой, и нечистоту отогнали вашими святыми наставлениями, и отлично упасли Христово стадо, порученное вам, Богомудрый Киприан со славным Фотием и с твердым Ионой, молитесь Христу Богу, да спасет души наши."},
  {"id": "ru-mol-0238", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0239", "section": "service", "who": "rubric", "text": "Кириллу, архиеп. Александрийскому,"},
  {"id": "ru-mol-0240", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0241", "section": "service", "who": "reader", "text": "Перевод: Православия наставник, учитель благочестия и чистоты, вселенной светильник, архиереев Богодухновенное украшение, Кирилл премудрый, учением твоим ты все просветил, лира духовная, моли Христа Бога о спасении наших душ."},
  {"id": "ru-mol-0242", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0243", "section": "service", "who": "rubric", "text": "Кириллу, еп. Туровскому,"},
  {"id": "ru-mol-0244", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0245", "section": "service", "who": "reader", "text": "Перевод: Благочестия ревнитель и поборник, монахов и столпников честь, святитель Туровской паствы, преславный, одаренный красноречием учитель, светлым учением Богоразумия своего просветивший все концы русской земли, в молитве к Богу благодатный помощник грешников, Кирилл Богомудрый, моли Христа Бога утвердиться нам, соотечественникам твоим, в Православии, благочестии и единомыслии."},
  {"id": "ru-mol-0246", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0247", "section": "service", "who": "rubric", "text": "Константину, митр. Киевскому и всея России, блж.,"},
  {"id": "ru-mol-0248", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0249", "section": "service", "who": "reader", "text": "Перевод: Апостолов преемник, разделяющий единый престол со архиереями, всей России пастырь и учитель, всеблаженный отче Константин, Владыке всех молись даровать мир твоей пастве и спасение душам нашим, и великую милость."},
  {"id": "ru-mol-0250", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0251", "section": "service", "who": "rubric", "text": "Леонтию, еп. Ростовскому,"},
  {"id": "ru-mol-0252", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0253", "section": "service", "who": "reader", "text": "Перевод: Апостолов преемник и верный молитвенник к Богу, добродетелями ты поднялся на высоту Небесную, и любовь посвятил Любящему тебя, и неверующих людей обратил ты в веру. Потому сейчас, радуясь вместе с ангелами, предстоишь Престолу славы всех Царя Христа Бога. Молись, святитель Леонтий, да спасет души наши."},
  {"id": "ru-mol-0254", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0255", "section": "service", "who": "rubric", "text": "Луке (Войно-Ясенецкому), архиеп. Крымскому, исп.,"},
  {"id": "ru-mol-0256", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0257", "section": "service", "who": "reader", "text": "Перевод: Вестник спасительного пути, исповедник и архипастырь Крымской земли, истинный хранитель отеческих преданий, столп непоколебимый, учитель Православия, врач, умудренный Богом, святитель Лука, Христа Спасителя непрестанно моли веру непоколебимую православным подарить, и спасение, и великую милость."},
  {"id": "ru-mol-0258", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0259", "section": "service", "who": "rubric", "text": "Льву, папе Римскому,"},
  {"id": "ru-mol-0260", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0261", "section": "service", "who": "reader", "text": "Перевод: Православия наставник, благочестия учитель и чистоты, светильник вселенной, архиереев Богодухновенное украшение, Лев премудрый, учениями твоими ты всех просветил, лира духовная. Моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0262", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0263", "section": "service", "who": "rubric", "text": "Макарию, митр. Московскому,"},
  {"id": "ru-mol-0264", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0265", "section": "service", "who": "reader", "text": "Перевод: Единонравного великим пастырям и единомысленного вселенским учителям, Божией Премудрости служителя превосходного, блаженству одноименного (Макарий от греч. μακάριος — блаженный), сегодня, верующие, все воспоем: «Христа Бога моли, святитель Макарий, мир умиротворить и спасти души наши»."},
  {"id": "ru-mol-0266", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0267", "section": "service", "who": "rubric", "text": "Максиму Новому, бывшему деспоту Сербскому,"},
  {"id": "ru-mol-0268", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0269", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0270", "section": "service", "who": "rubric", "text": "Марку, архиеп. Ефесскому,"},
  {"id": "ru-mol-0271", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0272", "section": "service", "who": "reader", "text": "Перевод: Православия наставник, новшеств (еретических) противоборник, высота веры, Церкви светильник, учителей Богодухновенный пример, Марк всемудрый, писаниями твоими всех просветил ты, лира духовная, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0273", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0274", "section": "service", "who": "rubric", "text": "Мартину Исповеднику, папе Римскому,"},
  {"id": "ru-mol-0275", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0276", "section": "service", "who": "reader", "text": "Перевод: Ты верно изложил повеления заповедей, просветил всех Божественным учением, победил ереси, умудренный Богом Мартин, достойный особого почитания святитель, вспоминай нас, служитель Христов, так, чтобы твоим обращением к Нему, ты устроил нашу жизнь мирной."},
  {"id": "ru-mol-0277", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0278", "section": "service", "who": "rubric", "text": "Мелетию, архиеп. Харьковскому,"},
  {"id": "ru-mol-0279", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0280", "section": "service", "who": "reader", "text": "Перевод: Ты познал, что мирские блага временны и преходящи, с юности постническую и полную трудов жизнь возлюбил, всеблаженный, иерархов слава и преподобных честь, Предвечного Слова усердный благовестник, обездоленных и несчастных кров и прибежище. Потому в молитвах пребывая, бодрствовать со Христом старался ты (Мф.24:42) и, Его взыскуя, венец неувядаемый со всеми святыми обрел ты, отче наш, святитель Мелетий, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0281", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0282", "section": "service", "who": "rubric", "text": "Митрофану, еп. Воронежскому,"},
  {"id": "ru-mol-0283", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0284", "section": "service", "who": "reader", "text": "Перевод: Правилом веры и образом кротости своим словом и жизнью для паствы твоей, отче смиренномудрый Митрофан, ты был. Потому и в сиянии святости ярче солнца воссиял ты, украшенный венцом нетления и славы, моли Христа Бога о спасении в мире страны нашей и города твоего."},
  {"id": "ru-mol-0285", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0286", "section": "service", "who": "rubric", "text": "Михаилу, первому митр. Киевскому,"},
  {"id": "ru-mol-0287", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0288", "section": "service", "who": "reader", "text": "Перевод: Сегодня пророчество Первозванного апостола исполнилось: ибо вот, на этих горах воссияла благодать и вера умножилась. Одряхлевшие в неверии Божественной купелью возродились и стали людьми, взятыми в удел, царским священством, народом святым (1Пет.2:9), Христовым стадом, которому ты явился первым пастырем, ранее Крещением послуживший. И сейчас, предстоя Владыке Христу Богу, моли всем людям русским спастись, имея дерзновение, как иерарх Божий и священнослужитель."},
  {"id": "ru-mol-0289", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0290", "section": "service", "who": "rubric", "text": "Модесту, архиеп. Иерусалимскому,"},
  {"id": "ru-mol-0291", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0292", "section": "service", "who": "reader", "text": "Перевод: Свято прожив, Богомудрый Модест, святительской одеждой украшен, пастырь Иерусалима блаженнейший, радуясь, сейчас Христу предстоишь и озаряешь все концы (вселенной) чудесами, будь же помощником призывающим тебя, молясь, отче, обо всех нас."},
  {"id": "ru-mol-0293", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0294", "section": "service", "who": "rubric", "text": "Моисею, архиеп. Новгородскому,"},
  {"id": "ru-mol-0295", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0296", "section": "service", "who": "reader", "text": "Перевод: Чистотой жизни твоей, пощением, молитвами и трудами, ты стал сосудом почтенным у Владыки Христа (Рим.9:21), Даровавшего тебя стаду своему, как неотъемлемое сокровище, обогащающее всех чудесами. Потому и мы, собравшись у раки с мощами твоими, с верой и любовью взываем: моли о нас, почитаемый архиерей, Моисей отче наш."},
  {"id": "ru-mol-0297", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0298", "section": "service", "who": "rubric", "text": "Нектарию Эгинскому, митр. Пентапольскому,"},
  {"id": "ru-mol-0299", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0300", "section": "service", "who": "reader", "text": "Перевод: Благочестиво прожив, как мудрый иерарх, прославил ты Господа добродетельной жизнью, Нектарий преподобный. Потому прославлен силой Утешителя, святые мощи твои изгоняют демонов и исцеляют больных, с верой приходящих к тебе."},
  {"id": "ru-mol-0301", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0302", "section": "service", "who": "rubric", "text": "Никите, Затворнику Печерскому, еп. Новгородскому,"},
  {"id": "ru-mol-0303", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0304", "section": "service", "who": "reader", "text": "Перевод: Насладившись, Богомудрый, воздержанием и желания плоти укротив, ты воссел на святительский престол, и как яркая звезда, просвещая сердца верующих сиянием чудес твоих, отче наш, святитель Никита, и сейчас моли Христа Бога о спасении наших душ."},
  {"id": "ru-mol-0305", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0306", "section": "service", "who": "rubric", "text": "Николаю, архиеп. Мир Ликийских, чудотворцу,"},
  {"id": "ru-mol-0307", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0308", "section": "service", "who": "reader", "text": "Перевод: Правилом веры и образом кротости, воздержания учителем явила тебя стаду твоему непреложная Истина. Потому ты приобрел смирением – высокое, нищетою – богатство. Отче, святитель Николай, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0309", "section": "service", "who": "rubric", "text": "Ин тропарь, на перенесение мощей,"},
  {"id": "ru-mol-0310", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0311", "section": "service", "who": "reader", "text": "Перевод: Настал день светлого торжества, город Бари радуется, и с ним вся вселенная ликует в псалмопениях и песнопениях духовных, ибо сегодня священное торжество в честь перенесения почитаемых и подающих многие исцеления мощей святителя и чудотворца Николая, воссиявшего как незакатное солнце яркими лучами, разгоняющими тьму искушений и бед от взывающих с верой: «Спасай нас как заступник наш великий, Николай»."},
  {"id": "ru-mol-0312", "section": "service", "who": "rubric", "text": "Ин тропарь, на рождество,"},
  {"id": "ru-mol-0313", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0314", "section": "service", "who": "reader", "text": "Перевод: Чудесное и прославляемое твое рождение, святитель Николай, сегодня светло празднует Православная Церковь, ибо тем, что ты стоял на ногах (никем не поддерживаемый, во время Крещения в купели), показал тебя Господь и провозгласил быть светилом и учителем для мирян, обогащающим весь мир и просвещающим чудесами. Потому взываем к тебе: «Моли Христа Бога о спасении наших душ»."},
  {"id": "ru-mol-0315", "section": "service", "who": "rubric", "text": "Ин тропарь, пред иконой «Зарайская»,"},
  {"id": "ru-mol-0316", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0317", "section": "service", "who": "rubric", "text": "Ин тропарь, на перенесение Великорецкой иконы из Вятки в Москву,"},
  {"id": "ru-mol-0318", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0319", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0320", "section": "service", "who": "rubric", "text": "Нифонту, патриарху Константинопольскому,"},
  {"id": "ru-mol-0321", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0322", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0323", "section": "service", "who": "rubric", "text": "Нифонту, еп. Новгородскому,"},
  {"id": "ru-mol-0324", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0325", "section": "service", "who": "reader", "text": "Перевод: Поскольку ты по образу действий был истинным защитником православных преданий Восточной Церкви, ты удостоился видеть великого из отцов — Феодосия — после его смерти, как живого, возвещающего тебе наследие Царствия Небесного. Его же неизреченных красот неразлучно наслаждаясь, моли и о нас, детях твоих, Нифонт, достойный всяческих похвал."},
  {"id": "ru-mol-0326", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0327", "section": "service", "who": "rubric", "text": "Павлу, патр. Константинопольскому, исп.,"},
  {"id": "ru-mol-0328", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0329", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0330", "section": "service", "who": "rubric", "text": "Павлу, митр. Тобольскому,"},
  {"id": "ru-mol-0331", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0332", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0333", "section": "service", "who": "rubric", "text": "Петру, митр. Московскому, всея России чудотворцу,"},
  {"id": "ru-mol-0334", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0335", "section": "service", "who": "reader", "text": "Перевод: Прежде бесплодная земля, ныне веселись: ибо вот, Христос светильник в тебе показал, ярко сияющий в мире и исцеляющий недуги и болезни наши. Потому ликуй и веселись со дерзновением: ибо святитель Всевышнего все это совершающий."},
  {"id": "ru-mol-0336", "section": "service", "who": "rubric", "text": "Ин тропарь, на перенесение мощей,"},
  {"id": "ru-mol-0337", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0338", "section": "service", "who": "reader", "text": "Перевод: Сегодня настал почитаемый всеми праздник перенесения священных мощей твоих, святитель Петр, особо радующий твое стадо, и верное отечество, и людей, о которых не прекращай молиться Христу Богу, чтобы дарованной от Него тебе пастве сохраниться в безопасности от ухищрений врагов и спастись душам нашим."},
  {"id": "ru-mol-0339", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0340", "section": "service", "who": "rubric", "text": "Питириму, еп. Великопермскому,"},
  {"id": "ru-mol-0341", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0342", "section": "service", "who": "reader", "text": "Перевод: Православия наставник, благочестия учитель и милости сокровищница, архиереев украшение, народа зырянского наставник, святитель Питирим, жизнь свою за Христа положивший, моли Единого Человеколюбца о пастве твоей и обо всех с любовью почитающих память твою."},
  {"id": "ru-mol-0343", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0344", "section": "service", "who": "rubric", "text": "Питириму, еп. Тамбовскому,"},
  {"id": "ru-mol-0345", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0346", "section": "service", "who": "reader", "text": "Перевод: Веры и благочестия учитель, Церкви светильник, монашествующим образец, святитель Питирим премудрый, стадо твое благочестиво упас ты и ко Христу привел, потому украшенный венцом славы на Небесах, с нами на земле пребываешь духовно, сияя чудесами. Моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0347", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0348", "section": "service", "who": "rubric", "text": "Порфирию, архиеп. Газскому,"},
  {"id": "ru-mol-0349", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0350", "section": "service", "who": "reader", "text": "Перевод: Кто поведает о трудах и болезнях твоих, ведущих к благочестию, отче? Ибо днем и ночью непрестанно трудясь, от нечестия Газу очистил, благочестие насадил ты, потому, как покровитель стада твоего, святитель Порфирий, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0351", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0352", "section": "service", "who": "rubric", "text": "Проклу, архиеп. Константинопольскому,"},
  {"id": "ru-mol-0353", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0354", "section": "service", "who": "reader", "text": "Перевод: Божественным началом премудрости, страхом Господним укрепившись (Прит.1:7), священным восхождением взошел ты в ученичество к Иоанну Златоусту и его архиерейского престола стал достоин по чистоте и добродетелям, став образом апостольского правила, живущий не для себя, но для Христа и стада своего. Потому в нетленную жизнь апостольски вселился ты, иерарх Прокл, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0355", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0356", "section": "service", "who": "rubric", "text": "Савве I, архиеп. Сербскому,"},
  {"id": "ru-mol-0357", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0358", "section": "service", "who": "reader", "text": "Перевод: Пути, ведущего к жизни, наставник, и первопрестольник, и учитель ты был, ибо сначала, святитель Савва, ты пришел и просветил отечество твое, и, породив его в Духе Святом, как масличные деревья в духовном раю посадил ты освященных чад твоих. Потому как разделяющего престол с апостолами и святителями почитая молим тебя: «Моли Христа Бога даровать нам великую милость»."},
  {"id": "ru-mol-0359", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0360", "section": "service", "who": "rubric", "text": "Савве II, архиеп. Сербскому,"},
  {"id": "ru-mol-0361", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0362", "section": "service", "who": "reader", "text": "Перевод: Подвиг веры и пример кротости, ты как сад посреди рая, преподобными делами твоими мир просвещаешь, потому к драгоценной раке с мощами твоими с любовью прикасаемся, целуем их и с верой взываем: «Приди на помощь воспевающим память святую твою и светоносную, святитель отче Савва счастливейший, молимся, Христу Богу молись о спасении душ наших»."},
  {"id": "ru-mol-0363", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0364", "section": "service", "who": "rubric", "text": "Святителям Московским: Петру, Алексию, Ионе, Филиппу и Ермогену,"},
  {"id": "ru-mol-0365", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0366", "section": "service", "who": "reader", "text": "Перевод: Первосвятители Российские, истинные хранители апостольских преданий, непоколебимые столпы, наставники Православия, Петр, Алексей, Иона, Филипп и Ермоген, Владыку всех молите даровать мир вселенной и душам нашим великую милость."},
  {"id": "ru-mol-0367", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0368", "section": "service", "who": "rubric", "text": "Серапиону, архиеп. Новгородскому,"},
  {"id": "ru-mol-0369", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0370", "section": "service", "who": "reader", "text": "Перевод: Твердым алмазом поистине, отец, ты явился, во всем будучи подобным Владыке своему и Господу, несправедливые гонения, радуясь, ты претерпел, потому и Христос сопричел тебя к лику святителей и мучеников и подарил тебя твоей пастве, как сокровище, которое невозможно отнять, обогащающее всех чудесами, так и мы, пришедшие к раке с мощами твоими, с любовью взываем к тебе: о великий из святителей и удивительный из мучеников, досточтимый архиерей, Серапион отец наш, моли всеблагого Бога о спасении душ наших."},
  {"id": "ru-mol-0371", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0372", "section": "service", "who": "rubric", "text": "Симону, еп. Владимирскому и Суздальскому,"},
  {"id": "ru-mol-0373", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0374", "section": "service", "who": "reader", "text": "Перевод: Известный составитель житий преподобных отцов Печерских, святитель Христов Симон преблаженный, молись настойчиво с ними Христу Богу, да сделает мирной жизнь нашу и в книги жизни да запишет нас, спасая души наши."},
  {"id": "ru-mol-0375", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0376", "section": "service", "who": "rubric", "text": "Собору Вселенских учителей и святителей Василию Великому, Григорию Богослову и Иоанну Златоустому,"},
  {"id": "ru-mol-0377", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0378", "section": "service", "who": "reader", "text": "Перевод: Апостолам единомысленные и вселенские учители, Владыку всего молите мир вселенной даровать и душам нашим великую милость."},
  {"id": "ru-mol-0379", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0380", "section": "service", "who": "rubric", "text": "Софронию, еп. Врачанскому (Болг.),"},
  {"id": "ru-mol-0381", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0382", "section": "service", "who": "reader", "text": "Перевод: Вооружившись щитом веры (Еф.6:16), мечом словесным безбожных агарян [мусульман, османов] повергая, стадо твоё уберег на земле, в Небесную же обитель вселившись, Христа моли даровать народу нашему мир и великую милость."},
  {"id": "ru-mol-0383", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0384", "section": "service", "who": "rubric", "text": "Софронию, еп. Иркутскому,"},
  {"id": "ru-mol-0385", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0386", "section": "service", "who": "reader", "text": "Перевод: С юности Христа возлюбил ты, блаженный Софроний, хорошо управлял иноческими обителями и был почтен архиерейским саном, ты духовно упас иркутскую паству, потому и после смерти принял от Бога дар чудотворения и молишь Христа Бога избавить нас от бед и спасти души наши."},
  {"id": "ru-mol-0387", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0388", "section": "service", "who": "rubric", "text": "Спиридону, еп. Тримифунтскому, чудотворцу,"},
  {"id": "ru-mol-0389", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0390", "section": "service", "who": "reader", "text": "Перевод: На соборе первом защитником истины и чудотворцем явился ты, Богоносный Спиридон, отче наш. Потому ты к мертвой в могиле обратился, и змею в золото превратил, и при пении святых молитв Ангелы сослужили тебе, священнейший! Слава Прославившему тебя, слава Увенчавшему тебя, слава Совершающему чрез тебя всем исцеления!"},
  {"id": "ru-mol-0391", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0392", "section": "service", "who": "rubric", "text": "Стефану, еп. Великопермскому,"},
  {"id": "ru-mol-0393", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0394", "section": "service", "who": "reader", "text": "Перевод: Устремлением к Богу с юного возраста, Стефан премудрый, ты воспламенился, поднял иго Христово (Мф.11:30) и людей, чьи сердца издавна заросли сорной травой неверия, посеяв в них Божественное семя, ты евангельски духовно породил. Потому, почитая твою преславную память, молим тебя: моли, Кого ты проповедал, о спасении наших душ."},
  {"id": "ru-mol-0395", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0396", "section": "service", "who": "rubric", "text": "Стефану Исповеднику, архиеп. Сурожскому,"},
  {"id": "ru-mol-0397", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0398", "section": "service", "who": "reader", "text": "Перевод: Как святитель ты служил вместе с бесплотными (ангелами), священномученик Стефан, ибо взяв Крест, как оружие, и став твердо против иконоборца и духоборцев, не поклоняющихся Пречистому Образу Христа Бога нашего, отсек ты всякую ересь лукавых. Потому получил мученический венец, избавив город твой Сурож от всякого зла. И сейчас молим тебя, святой, избавь нас от всяких злых искушений и бед, и вечной муки."},
  {"id": "ru-mol-0399", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0400", "section": "service", "who": "rubric", "text": "Тихону, еп. Амафунтскому,"},
  {"id": "ru-mol-0401", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0402", "section": "service", "who": "reader", "text": "Перевод: Пустынный житель и ангел во плоти, и чудотворцем явился ты, Богоносный отче наш Тихон, постом, бдением и молитвой получив Небесные дарования, исцеляешь болеющих и души с верой приходящих к тебе. Слава Давшему тебе силу, слава Венчавшему тебя, слава Подающему через тебя всем исцеления."},
  {"id": "ru-mol-0403", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0404", "section": "service", "who": "rubric", "text": "Тихону, еп. Воронежскому, Задонскому чудотворцу,"},
  {"id": "ru-mol-0405", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0406", "section": "service", "who": "reader", "text": "Перевод: Православия наставник, благочестия учитель, покаяния проповедник, подражатель Иоанну Златоусту, пастырь прекрасный, новый светильник России и чудотворец, паству твою отлично упас и писаниями твоими всех нас научил ты, потому венцом нетления украшен Пастыреначальником, моли Его о спасении душ наших."},
  {"id": "ru-mol-0407", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0408", "section": "service", "who": "rubric", "text": "Тихону, патриарху Московскому и всея Руси,"},
  {"id": "ru-mol-0409", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0410", "section": "service", "who": "reader", "text": "Перевод: В тяжелые времена избранный Богом ты в совершенной святости и любви прославил Его, являя в своем смирении — величие, в простоте и кротости — силу Божию. Положил душу за Церковь и паству свою, исповедник Патриарх святой Тихон, моли Христа Бога, Которому ты сораспялся (Гал.2:19), и сейчас спасти землю Русскую и паству твою."},
  {"id": "ru-mol-0411", "section": "service", "who": "rubric", "text": "Ин тропарь, на прославление,"},
  {"id": "ru-mol-0412", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0413", "section": "service", "who": "reader", "text": "Перевод: Апостольского учения ревнителя и Христовой Церкви пастыря доброго, жизнь свою за овец отдавшего (Ин.10:11), жребием Божиим избранного, Всероссийского патриарха Тихона прославим и к нему с верой и надеждой воззовем: «Представительством святительским ко Господу Церковь Русскую в спокойствии сохрани, рассеявшихся чад ее в единое стадо собери, отступивших от православной веры к покаянию обрати, страну нашу от междоусобной войны сохрани и мир Божий для людей испроси»."},
  {"id": "ru-mol-0414", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0415", "section": "service", "who": "rubric", "text": "Феодору, еп. Едесскому,"},
  {"id": "ru-mol-0416", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0417", "section": "service", "who": "reader", "text": "Перевод: Против желания приняв паству как епископ, но по своей воле подвизаясь о Божией Церкви, и неверующего царя Мавия обратив к вере с помощью земли от гроба Господня, и, вместе с телесной слепотой исцелив ему и душевную, научил его благочестию, вместе с тем и еретиков прогнав от Божией Церкви, как волков, почитаемый святитель Феодор, моли о спасении душ наших."},
  {"id": "ru-mol-0418", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0419", "section": "service", "who": "rubric", "text": "Феодору, архиеп. Ростовскому,"},
  {"id": "ru-mol-0420", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-0421", "section": "service", "who": "reader", "text": "Перевод: С юности, премудрый, прилежно подвизался и по благословению Святого Духа превеликую обитель воздвиг Пресвятой Богородицы в честь Рождества Ее, потоками же слез твоих бесплотных врагов потопил ты и жития твоего целомудрием соединился с собранием ангельским, преподобный отче Феодор, с ними же Христа Бога моли о спасении душ наших."},
  {"id": "ru-mol-0422", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0423", "section": "service", "who": "rubric", "text": "Феодору, еп. Суздальскому,"},
  {"id": "ru-mol-0424", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0425", "section": "service", "who": "reader", "text": "Перевод: В молитвенном бдении ты всегда болел сердцем о стаде своем, учением своим всех просветил ты, Феодор премудрый, потому Христа Бога моли в день памяти твоей даровать нам великую милость."},
  {"id": "ru-mol-0426", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0427", "section": "service", "who": "rubric", "text": "Феодосию, архиеп. Черниговскому,"},
  {"id": "ru-mol-0428", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0429", "section": "service", "who": "reader", "text": "Перевод: Украшение архиереев, святитель Феодосий, ты был светилом своему стаду, после чего преставился в вечные обители, молись у Престола Царя Славы об избавлении нас от наступающих бедствий и о спасении душ наших, святитель, по молитвам твоим."},
  {"id": "ru-mol-0430", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0431", "section": "service", "who": "rubric", "text": "Феоктисту, архиеп. Новгородскому,"},
  {"id": "ru-mol-0432", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0433", "section": "service", "who": "reader", "text": "Перевод: Божиего Слова Премудрости прекрасный служитель, Ангельской жизни истинный подражатель, Божественной чистоты любитель, разделяющий престол с архиереями, живущий вместе с преподобными, пастырская красота, Великого Новгорода слава, святитель почитаемый Феоктист, отче наш, Слово Божие, Кому в жизни послужил ты, моли о спасении душ наших."},
  {"id": "ru-mol-0434", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0435", "section": "service", "who": "rubric", "text": "Феофану, Затворнику Вышенскому, еп.,"},
  {"id": "ru-mol-0436", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0437", "section": "service", "who": "reader", "text": "Перевод: Православия наставник, благочестия учитель и чистоты, Вышенский подвижник, святитель Феофан, Богомудрый, писаниями твоими слово Божие объяснил ты и всем верующим путь ко спасению указал. Моли Христа Бога о спасении наших душ."},
  {"id": "ru-mol-0438", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0439", "section": "service", "who": "rubric", "text": "Филарету, митр. Московскому,"},
  {"id": "ru-mol-0440", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0441", "section": "service", "who": "reader", "text": "Перевод: Духа Святого благодать обретя, Богомудрый святитель Филарет, истину и праведность разумом просвещенным людям проповедовал ты, мир и милость сердцем сокрушенным страдающим явил ты, как учитель веры и страж неусыпный паству российскую жезлом правоты (Пс.44:7) сохранил ты. Потому, ко Христу Богу дерзновение имея, моли даровать Церкви укрепление и душам нашим спасение."},
  {"id": "ru-mol-0442", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0443", "section": "service", "who": "rubric", "text": "Филиппу II, митр. Московскому,"},
  {"id": "ru-mol-0444", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0445", "section": "service", "who": "rubric", "text": "Ин тропарь, глас 8"},
  {"id": "ru-mol-0446", "section": "service", "who": "reader", "text": "Перевод: Первосвятителей преемник, столп Православия, истины поборник, новый исповедник, святитель Филипп, положивший душу за паству твою! Как имеющий дерзновение ко Христу, моли за и город твой и за людей, почитающих по достоинству святую память твою."},
  {"id": "ru-mol-0447", "section": "service", "who": "rubric", "text": "Ин тропарь, на перенесение мощей,"},
  {"id": "ru-mol-0448", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-0449", "section": "service", "who": "reader", "text": "Перевод: Радостный воссиял день светлого торжества: сегодня расширяются церковные недра, принимая неоскудеваемое сотворенное Богом сокровище духовных даров, неисчерпаемый поток благодати из обильного источника чудес, чудотворные и священные мощи твои, святитель Филипп. Потому моли прославившего тебя Дародателя Христа Бога о воспевающих тебя и поклоняющихся священным мощам твоим."},
  {"id": "ru-mol-0450", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0451", "section": "service", "who": "rubric", "text": "Фотию, митр. Киевскому и всея Руси,"},
  {"id": "ru-mol-0452", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0453", "section": "service", "who": "reader", "text": "Перевод: Словам евангельским послушный и о Божественных учениях заботящийся, премудрый наставник, всегда размышляющий о страхе Господнем, устремляющийся в молитвах к Богу, заграждающий уста искажающим слово православной веры, апостолов преемник, утвердитель веры Христовой, пророчеств известитель, святитель Фотий, моли Христа Бога дать мир всему миру и спасти души наши."},
];

